<?php
declare(strict_types=1);
use App\Core\{Database,LegacyDatabase};
use App\Services\LegacyOfficer\LegacyOfficerPersonnelBackfillService;
require dirname(__DIR__).'/bootstrap.php';
$options=getopt('', ['dry-run','execute']);$execute=isset($options['execute']);if(!$execute&&!isset($options['dry-run'])){fwrite(STDERR,"Usage: php bin/backfill-legacy-officer-personnel.php --dry-run|--execute\n");exit(2);}
$service=new LegacyOfficerPersonnelBackfillService(LegacyDatabase::pdo(),Database::pdo());$result=$execute?$service->execute():$service->dryRun();$r=$execute?$result['report']:$result;
$labels=['Target Officers examined'=>'target_officers_examined','Target Officers mapped'=>'target_officers_mapped','Residential addresses available'=>'addresses_available','DOB available'=>'dob_available','DOB invalid'=>'dob_invalid','Telephone available'=>'telephone_available','Telephone invalid'=>'telephone_invalid','WhatsApp available'=>'whatsapp_available','WhatsApp invalid'=>'whatsapp_invalid','Email valid'=>'email_valid','Email invalid'=>'email_invalid','Email duplicate/shared'=>'email_duplicate','First appointment dates available'=>'first_appointment_available','First appointment dates invalid'=>'first_appointment_invalid','Permanent in Service'=>'permanent_in_service','Not Permanent in Service'=>'not_permanent_in_service','Permanency unknown'=>'permanency_unknown','Permanented dates available'=>'permanented_date_available','Permanented dates invalid'=>'permanented_date_invalid','Pension dates available'=>'pension_date_available','Pension dates invalid'=>'pension_date_invalid','Alias field conflicts'=>'alias_field_conflicts','Would update'=>'would_update','Warnings'=>'warnings','True blockers'=>'true_blockers'];
echo ($execute?'EXECUTION':'DRY RUN')." - Legacy Officer Personnel Backfill\n";foreach($labels as $label=>$key)echo "{$label}: {$r[$key]}\n";echo "Report: {$r['report_path']}\n";if($execute)echo "Execution run ID: {$result['run_id']}\nUpdated: {$result['updated']}\n";exit($r['true_blockers']>0?1:0);
